<?php $title='Enquiries';require 'includes/header.php';if(isset($_POST['status'])){$pdo->prepare("UPDATE enquiries SET status=? WHERE id=?")->execute([$_POST['status'],(int)$_POST['id']]);}$rows=$pdo->query("SELECT * FROM enquiries ORDER BY id DESC")->fetchAll();?><h1>Enquiries</h1><div class="table-responsive bg-white rounded-4 shadow-sm"><table class="table"><thead><tr><th>ID</th><th>Customer</th><th>Phone</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['customer_name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['created_at'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" onchange="this.form.submit()" class="form-select form-select-sm"><?php foreach(['New','Contacted','Quotation Sent','Completed','Cancelled'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></tbody></table></div><?php require 'includes/footer.php';?>